#include "icinga_agent_import.hpp"

#include <gtest/gtest.h>

using namespace icinga_agent;

namespace {
// zones.conf as `icinga2 node wizard` writes it on an agent.
const char *const wizard_zones = R"conf(/*
 * Generated by Icinga 2 node setup commands
 * on 2026-01-01 00:00:00 +0000
 */

object Endpoint "icinga-master.example.com" {
	host = "192.0.2.10"
	port = "5665"
}

object Zone "master" {
	endpoints = [ "icinga-master.example.com" ]
}

object Endpoint NodeName {
}

object Zone ZoneName {
	endpoints = [ NodeName ]
	parent = "master"
}

object Zone "global-templates" {
	global = true
}
)conf";
}  // namespace

TEST(IcingaAgentImport, NodeName) {
  EXPECT_EQ(parse_node_name("const PluginDir = \"x\"\nconst NodeName = \"WIN-Host-01.example.com\"\n"), "WIN-Host-01.example.com");
  // The wizard leaves it commented out when the name is the host's FQDN.
  EXPECT_EQ(parse_node_name("/* Our local instance name. */\n//const NodeName = \"localhost\"\n"), "");
  EXPECT_EQ(parse_node_name("# const NodeName = \"a\"\nconst  NodeName=\"b\""), "b");
  EXPECT_EQ(parse_node_name(""), "");
}

TEST(IcingaAgentImport, Comments) {
  EXPECT_EQ(strip_icinga_comments("a // b\nc # d\ne /* f\ng */ h"), "a \nc \ne   h");
  // Comment characters inside a string are text.
  EXPECT_EQ(strip_icinga_comments("host = \"http://x/#y\" // z"), "host = \"http://x/#y\" ");
}

TEST(IcingaAgentImport, EndpointsOfTheNodeWizard) {
  const std::vector<icinga_endpoint> endpoints = parse_endpoints(wizard_zones);
  ASSERT_EQ(endpoints.size(), 2u);
  EXPECT_EQ(endpoints[0].name, "icinga-master.example.com");
  EXPECT_EQ(endpoints[0].host, "192.0.2.10");
  EXPECT_EQ(endpoints[0].port, "5665");
  EXPECT_TRUE(endpoints[1].is_node_name);

  const std::vector<icinga_endpoint> parents = parent_endpoints(endpoints, "");
  ASSERT_EQ(parents.size(), 1u);
  EXPECT_EQ(parents[0].name, "icinga-master.example.com");
}

TEST(IcingaAgentImport, EndpointVariants) {
  // The agent named by its string, a parent the agent does not connect to, a
  // numeric port, one line, and an endpoint that is commented out.
  const std::vector<icinga_endpoint> endpoints = parse_endpoints(R"conf(
    object Endpoint "agent-1" { }
    object Endpoint "sat-1" { host = "sat-1.example.com"; port = 5666; log_duration = 0 }
    object Endpoint "sat-2" { log_duration = 0 }
    // object Endpoint "old" { host = "old.example.com" }
    object Zone "satellite" { endpoints = [ "sat-1", "sat-2" ] }
  )conf");
  ASSERT_EQ(endpoints.size(), 3u);
  EXPECT_EQ(endpoints[1].host, "sat-1.example.com");
  EXPECT_EQ(endpoints[1].port, "5666");
  EXPECT_TRUE(endpoints[2].host.empty());

  const std::vector<icinga_endpoint> parents = parent_endpoints(endpoints, "agent-1");
  ASSERT_EQ(parents.size(), 2u);
  EXPECT_EQ(parents[0].name, "sat-1");
  EXPECT_EQ(parents[1].name, "sat-2");
}
